			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_cybdir_sum_o), de
			ld hl, 0
			ld (var_cybdir_sum_sum), hl
			ld hl, 0
			ld (var_cybdir_sum_i), hl
			ld hl, 0
			ld (var_cybdir_sum_s), hl
			ld (var_cybdir_sum_s+2), hl
			ld (p_cybdir_sum_rs), sp
			ld sp, p_cybdir_sum
			jp ntc_xn
